function nearestEnemy(e,r){if(!stats(e).damage)return null;const cached=get(e.autoTarget);if(cached&&hostile(cached,e)&&canHit(e,cached)&&(e.team!==0||seen(cached))&&dist(e,cached)-cached.size<r)return cached;if(state.time<(e.seekAt||0))return null;e.seekAt=state.time+.15+(e.id%5)*.02;let best=null,bd=r;combatGrids[e.team===0?1:0].query(e.x,e.y,r+64,t=>{if(!canHit(e,t)||t.hp<=0||(e.team===0&&!seen(t)))return;const d=dist(e,t)-t.size;if(d<bd){best=t;bd=d;}});e.autoTarget=best?.id;return best;}
