function actionKey(a){return a.type||'command:'+a.key;}
function renderActions(){const panel=$('actions'),existing=new Map(Array.from(panel.children).map(b=>[b.dataset.command,b])),keep=new Set();
 for(let i=0;i<actionList.length;i++){const a=actionList[i],key=actionKey(a),t=a.type?definition(a.type):null;keep.add(key);let b=existing.get(key);
 if(!b){b=document.createElement('button');b.type='button';b.dataset.command=key;for(const tag of ['kbd','b','small'])b.appendChild(document.createElement(tag));}
 const cls='action '+(a.locked||t&&!canPay(a.type)?'unavailable':'');if(b.className!==cls)b.className=cls;
 const text=[a.key,t?t.name:a.label,a.locked?(a.type?'Requiere nivel II':'Investigando mejora…'):t?'◆ '+t.cost+(t.gas?' · ▰ '+t.gas:''):a.sub];
 for(let j=0;j<text.length;j++)if(b.children[j].textContent!==text[j])b.children[j].textContent=text[j];
 if(panel.children[i]!==b)panel.insertBefore(b,panel.children[i]||null);
 }
 for(const [key,b] of existing)if(!keep.has(key))b.remove();
}

