 if(d.building&&e.level<2&&UPGRADES[e.type]){const u=UPGRADES[e.type];actionList.push({label:u.name,sub:'◆ '+u.cost+' · ▰ '+u.gas+' · '+u.time+' s',key:'U',locked:!!e.research,fn:upgrade});}
