$('groups').addEventListener('click',e=>{const b=e.target.closest('button');if(b)recallGroup(b.dataset.group);});
$('actions').addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!state.paused&&!state.ended)actionList.find(a=>actionKey(a)===b.dataset.command)?.fn();});
function hit(e,resource=false){const p=screen(e),r=(resource?(e.kind==='wood'?43:28):e.size+8)*zoom,air=!resource&&stats(e).domain==='air'?35*zoom:0;return mouse.x>p.x-r&&mouse.x<p.x+r&&mouse.y>p.y-r*1.7-air&&mouse.y<p.y+8*zoom-air;}
function pointer(event){const r=canvas.getBoundingClientRect();mouse.x=(event.clientX-r.left)*width/r.width;mouse.y=(event.clientY-r.top)*height/r.height;const world=Terrain.pick(map,mouse.x/zoom+camera.x,mouse.y/zoom+camera.y);mouse.wx=world.x;mouse.wy=world.y;}
function edgePointer(event){const r=canvas.getBoundingClientRect();const right=Math.min(r.right??r.left+r.width,($('gameHud')?.getBoundingClientRect?.().left)||Infinity);const top=Math.max(r.top,($('topHud')?.getBoundingClientRect?.().bottom)||0),bottom=r.top+r.height;const x=event.clientX,y=event.clientY;edgeX=x>=r.left&&x<=right&&y>=top&&y<=bottom?(x<r.left+18?-1:x>right-18?1:0):0;edgeY=x>=r.left&&x<=right&&y>=top&&y<=bottom?(y<top+18?-1:y>bottom-18?1:0):0;}
canvas.addEventListener('pointermove',e=>{pointer(e);edgePointer(e);});canvas.addEventListener('pointerleave',()=>{edgeX=edgeY=0;});
$('idleWorkers').onclick=selectIdle;
canvas.addEventListener('pointerdown',event=>{pointer(event);canvas.focus();if(event.button!==0||!state.started||state.paused||state.ended)return;if(rallyMode){const resource=nodes.find(n=>visible.has(tileKey(n.x,n.y))&&hit(n,true));setRally(resource?.x??mouse.wx,resource?.y??mouse.wy,'left');return;}if(placing){place(Math.round(mouse.wx/8)*8,Math.round(mouse.wy/8)*8,event.shiftKey);return;}if(attackMode){orderAt(mouse.wx,mouse.wy,true);return;}drag={x:mouse.x,y:mouse.y,wx:mouse.wx,wy:mouse.wy};canvas.setPointerCapture?.(event.pointerId);});
canvas.addEventListener('pointerup',event=>{pointer(event);if(!drag)return;let chosen=[];resourceSelection=null;if(dist(drag,mouse)>6){chosen=units().filter(e=>!e.insideRef&&!e.carrier).filter(e=>{const p=screen(e);return p.x>=Math.min(drag.x,mouse.x)&&p.x<=Math.max(drag.x,mouse.x)&&p.y>=Math.min(drag.y,mouse.y)&&p.y<=Math.max(drag.y,mouse.y);}).map(e=>e.id);}else{const e=entities.filter(e=>seen(e)&&hit(e)).sort((a,b)=>dist(screen(a),mouse)-dist(screen(b),mouse))[0];if(e)chosen=[e.id];else{const n=nodes.find(n=>visible.has(tileKey(n.x,n.y))&&hit(n,true));if(n)resourceSelection=n.id;else if(selected().some(e=>e.team===0&&e.type!=='core'&&Object.values(TYPES).some(t=>t.host===e.type))){setRally(mouse.wx,mouse.wy,'left');drag=null;return;}}}selection=limitSelection(event.shiftKey&&resourceSelection===null?[...new Set([...selection,...chosen])]:chosen);drag=null;if(selection.length)effect('select',selected()[0]);else if(resourceSelection!==null)effect('select');renderUI();});
canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('dblclick',()=>{const e=selected()[0];if(e&&!TYPES[e.type].building&&e.team===0){selection=limitSelection(units().filter(u=>u.type===e.type&&inView(u,0)).map(u=>u.id));renderUI();}});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();pointer(e);if(placing||attackMode||rallyMode){placing=null;attackMode=false;rallyMode=false;renderUI();}else{const target=entities.find(e=>(e.team||e.build||isRefinery(e.type)||e.type==='transport')&&seen(e)&&hit(e))||nodes.find(n=>visible.has(tileKey(n.x,n.y))&&hit(n,true));orderAt(target?.x??mouse.wx,target?.y??mouse.wy);}});
function moveMini(e){const r=mini.getBoundingClientRect(),p=project(clamp((e.clientX-r.left)/r.width,0,1)*W,clamp((e.clientY-r.top)/r.height,0,1)*H);camera.x=p.x-width/(2*zoom);camera.y=p.y-height/(2*zoom);clampCamera();}
mini.addEventListener('pointerdown',e=>{if(e.button!==0||!state.started||state.paused||state.ended)return;e.preventDefault();miniDragging=true;edgeX=edgeY=0;mini.setPointerCapture?.(e.pointerId);moveMini(e);});
mini.addEventListener('pointermove',e=>{if(miniDragging)moveMini(e);});
for(const name of ['pointerup','pointercancel','lostpointercapture'])mini.addEventListener(name,()=>{miniDragging=false;});

function setZoom(value){miniClock=-Infinity;const cx=camera.x+width/(2*zoom),cy=camera.y+height/(2*zoom);zoom=clamp(value,.45,1.75);camera.x=cx-width/(2*zoom);camera.y=cy-height/(2*zoom);clampCamera();renderUI();}
$('zoomIn').onclick=()=>setZoom(zoom+.15);$('zoomOut').onclick=()=>setZoom(zoom-.15);canvas.addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom+(e.deltaY<0?.1:-.1));},{passive:false});
function togglePause(){edgeX=edgeY=0;miniDragging=false;if(!state.started||state.ended)return;state.paused=!state.paused;sound?.pause(state.paused);keys={};$('pause').textContent=state.paused?'▶':'Ⅱ';$('pause').title=state.paused?'Reanudar (P)':'Pausar (P)';}
window.addEventListener('keydown',event=>{if(document.querySelector('dialog[open]'))return;const k=event.key.toLowerCase();if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))event.preventDefault();if(event.repeat)return;if(k==='p'){togglePause();return;}if(k==='escape'){placing=null;attackMode=false;rallyMode=false;renderUI();return;}if(k===' '){centerBase();return;}if(/^[0-9]$/.test(k)){event.preventDefault();resourceSelection=null;if(event.ctrlKey||event.metaKey)saveGroup(k);else recallGroup(k);return;}if(state.paused)return;const action=actionList.find(a=>a.key.toLowerCase()===k);if(action){event.preventDefault();action.fn();return;}keys[event.key]=true;});
window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{keys={};edgeX=edgeY=0;miniDragging=false;if(state.started&&!state.paused&&!state.ended&&!document.querySelector('dialog[open]'))togglePause();});$('pause').onclick=togglePause;
let audioWasPaused=false;$('audioSettings').onclick=()=>{audioWasPaused=state.paused;if(state.started&&!state.paused&&!state.ended)togglePause();$('audioDialog').showModal();};$('audioDialog').addEventListener('close',()=>{if(state.started&&!audioWasPaused&&state.paused&&!state.ended)togglePause();});
let helpWasPaused=false;$('help').onclick=()=>{helpWasPaused=state.paused;if(state.started&&!state.paused&&!state.ended)togglePause();$('manual').showModal();};$('closeManual').onclick=()=>$('manual').close();$('manual').addEventListener('close',()=>{if(state.started&&!helpWasPaused&&state.paused&&!state.ended)togglePause();});
function newGame(){if(state.started&&!state.paused&&!state.ended)togglePause();$('intro').showModal();}$('restart').onclick=()=>{helpWasPaused=true;$('manual').close();newGame();};$('again').onclick=()=>{$('result').close();newGame();};$('start').onclick=()=>{reset();state.started=true;sound?.start(state.faction).then(ok=>{if(!ok)toast('Audio no disponible. El juego sigue sin sonido.');});$('intro').close();canvas.focus();toast('Colonia desplegada. Tus recolectores ya están trabajando.');};$('intro').addEventListener('cancel',e=>{e.preventDefault();if(state.started)$('intro').close();});
window.addEventListener('resize',resize);function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;update(dt);draw();uiClock+=dt;if(uiClock>.22){renderUI();uiClock=0;}requestAnimationFrame(frame);}resize();reset();$('intro').showModal();requestAnimationFrame(frame);
if(typeof globalThis.__PIXEL_TEST__==='function')globalThis.__PIXEL_TEST__({reset,update,spawn,train,beginBuild,place,orderAt,validSite,supply,updateVision,draw,renderUI,TYPES,definition,hostile,upgrade,productionPoint,move,canHit,dockSite,fire,drawMini,getResourcePulses:()=>resourcePulses,getAttackAlerts:()=>attackAlerts,TECHS,researchTech,techCost,unloadTransport,cargoUsed,groundLanding,destruction,getParticles:()=>particles,screen,HARVEST_SECONDS,harvestLoad,idleWorkers,selectIdle,getCamera:()=>({...camera}),getAttackMode:()=>attackMode,CAPACITY,MAX_UNITS,MAX_GROUP,GAS_SLOTS,setRally,applyRally,population,saveGroup,recallGroup,tradeFish,getGroups:()=>groups,getSelection:()=>selection,getSpatialStats:()=>({combat:spatial.visits+combatGrids[0].visits+combatGrids[1].visits,collision:separation.visits}),getMap:()=>map,selectResource:id=>{selection=[];resourceSelection=id;renderUI();},getState:()=>state,getEntities:()=>entities,getNodes:()=>nodes,select:ids=>{resourceSelection=null;selection=limitSelection(ids);renderUI();},setStarted:()=>state.started=true});
